insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$lourdes$q$, $q$https://www.lourdes.sp.gov.br/portal/leis_decretos/1393/ (Lei 1.893/2023) ; https://www.lourdes.sp.gov.br/portal/leis_decretos/1446/ (Decreto 6.009/2023)$q$, $q$Atos oficiais de Lourdes: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários 2022 (dados públicos, citar a fonte).$q$, 2, $q$Lei 1.893/2023: caminhões a partir de 5 eixos e veículos longos pesados proibidos nas vias públicas da cidade; alternativa obrigatória pelo anel viário (Contorno de Lourdes). O art. 2º do Dec. 6.009/2023 (todos os caminhões e ônibus, salvo carga e descarga) fica desativado: depende das placas e vai além da lei.$q$);
